SELECT P.FINPROD_MARKET_ID finprodMarketId, P.FINPROD_ID finprodId, TYPE.TYPE_6 finprodType2, V.VAL_DATE valDate, V.VALUATION valuation, V.CREATE_TIME importDay, V.PUBLISH_DATE publishDate, CUST.CUSTOMER_NAME fundManager, V.TOTAL_VALUE totalValue, V.REST_NET_VALUE restNetValue, V.DAY7_YEAR_YIELD * 100 day7YearYield FROM FIN_PRODUCT P INNER JOIN FIN_PRODUCT_VALUATION V ON P.FINPROD_MARKET_ID = V.FINPROD_ID and p.FINPROD_TYPE2 = V.FINPROD_TYPE2 INNER JOIN FIN_PRODUCT_TYPE TYPE ON P.FINPROD_ID = TYPE.FINPROD_ID LEFT JOIN MST_CUSTOMER_INFO CUST ON CUST.CUSTOMER_ID = P.MANAGER AND CUST.IS_ASSTE_MANAGER = #{yes,jdbcType=VARCHAR}
P.FINPROD_TYPE2 = #{finprodType2,jdbcType=VARCHAR}
AND P.FINPROD_MARKET_ID like concat_ws('','%',#{finprodId,jdbcType=VARCHAR},'%')
AND CUST.CUSTOMER_NAME like concat_ws('','%',#{fundManager,jdbcType=VARCHAR},'%')
AND V.VAL_DATE = STR_TO_DATE(#{valDate},'%Y-%m-%d')

SELECT P.FINPROD_MARKET_ID finprodMarketId, P.FINPROD_ID finprodId, TYPE.TYPE_6 finprodType2, V.VAL_DATE valDate, V.VALUATION valuation, V.CREATE_TIME importDay, V.PUBLISH_DATE publishDate, CUST.CUSTOMER_NAME fundManager, V.TOTAL_VALUE totalValue, V.REST_NET_VALUE restNetValue, V.DAY7_YEAR_YIELD * 100 day7YearYield FROM FIN_PRODUCT P INNER JOIN FIN_PRODUCT_VALUATION V ON P.FINPROD_MARKET_ID = V.FINPROD_ID and p.FINPROD_TYPE2 = V.FINPROD_TYPE2 INNER JOIN FIN_PRODUCT_TYPE TYPE ON P.FINPROD_ID = TYPE.FINPROD_ID LEFT JOIN MST_CUSTOMER_INFO CUST ON CUST.CUSTOMER_ID = P.MANAGER AND CUST.IS_ASSTE_MANAGER = #{yes,jdbcType=VARCHAR}
P.FINPROD_TYPE2 = #{finprodType2,jdbcType=VARCHAR}
AND P.FINPROD_MARKET_ID = #{finprodId,jdbcType=VARCHAR}
AND V.VAL_DATE = STR_TO_DATE(#{valDate},'%Y-%m-%d')
